/** Uploaded kits fall back to English, then to any language that has the format. */
/** Built-in kit and media files (scripts/build-kits.mjs, public/media) exist in these languages; others get English. */
export const FILE_LANGS = ["en", "ar"];
const fileLang = (lang: string) => (FILE_LANGS.includes(lang) ? lang : "en");
